<?php declare(strict_types=1); namespace Annam; $title=($category['name']??'Shop').' · '.$store->name(); ?>
<section class="wrap php-store-section"><h1><?= e($category['name']??'Shop the pantry') ?></h1><p>Traditional favourites, packed with care.</p><form class="php-search" method="get"><input name="q" value="<?= e($query) ?>" placeholder="Search products" aria-label="Search products"><button class="btn" type="submit">Search</button></form><nav class="php-tabs php-scroll"><a href="/shop/" class="<?= !$category?'selected':'' ?>">All items</a><?php foreach ($store->categories() as $cat): if (!$cat['active']||!$cat['slug']) continue; ?><a href="/shop/<?= e($cat['slug']) ?>/" class="<?= ($category['id']??null)===$cat['id']?'selected':'' ?>"><?= e($cat['name']) ?></a><?php endforeach; ?></nav><ul class="php-product-grid"><?php foreach ($products as $product) require __DIR__.'/card.php'; ?></ul><?php if (!$products): ?><p>No matching products.</p><?php endif; ?></section>
